fn fingerprintAdmissionReport(report: Admission.AdmissionReport) u64 {
    var hasher = std.hash.Wyhash.init(0);
    hashBytes(&hasher, "world.admission_report.fingerprint");
    hashU64(&hasher, world_admission_report_fingerprint_version);
    hashBool(&hasher, report.accepted);
    hashU64(&hasher, @intFromEnum(report.mode));
    hashU64(&hasher, report.package_fingerprint);
    hashU64(&hasher, report.manifest_fingerprint);
    hashOptionalU64(&hasher, report.target_ref_fingerprint);
    hashOptionalU64(&hasher, report.module_ref_fingerprint);
    hashOptionalU64(&hasher, report.target_match_fingerprint);
    hashOptionalU64(&hasher, report.import_set_fingerprint);
    hashOptionalU64(&hasher, report.environment_acceptance_report_fingerprint);
    hashOptionalU64(&hasher, report.run_permit_fingerprint);
    hashLinkerMetadataIfPresent(&hasher, report.link_plan_fingerprint, report.linker_certificate_fingerprint, report.assembly_fingerprint);
    hashOptionalU64(&hasher, report.handoff_preflight_report_fingerprint);
    if (report.capsule_image_fingerprint != null or
        report.capsule_certificate_fingerprint != null or
        report.capsule_thaw_plan_fingerprint != null or
        report.capsule_restore_report_fingerprint != null)
    {
        hashBytes(&hasher, "world.admission_report.capsule_refs");
        hashU64(&hasher, world_capsule_image_fingerprint_version);
        hashOptionalU64(&hasher, report.capsule_image_fingerprint);
        hashOptionalU64(&hasher, report.capsule_certificate_fingerprint);
        hashOptionalU64(&hasher, report.capsule_thaw_plan_fingerprint);
        hashOptionalU64(&hasher, report.capsule_restore_report_fingerprint);
    }
    if (report.required_actuator_count != 0 or
        report.actuation_receipt_count != 0 or
        report.replay_only_actuation_feasible or
        report.verify_actuation_feasible or
        report.actuation_binding_refs.len != 0 or
        report.actuation_receipt_refs.len != 0)
    {
        hashBytes(&hasher, "world.admission_report.actuation");
        hashU64(&hasher, report.required_actuator_count);
        hashU64(&hasher, report.actuation_receipt_count);
        hashBool(&hasher, report.replay_only_actuation_feasible);
        hashBool(&hasher, report.verify_actuation_feasible);
        hashU64(&hasher, report.actuation_binding_refs.len);
        for (report.actuation_binding_refs) |fingerprint| hashU64(&hasher, fingerprint);
        hashU64(&hasher, report.actuation_receipt_refs.len);
        for (report.actuation_receipt_refs) |fingerprint| hashU64(&hasher, fingerprint);
    }
    hashU64(&hasher, report.blockers.len);
    for (report.blockers) |blocker| hashU64(&hasher, @intFromEnum(blocker));
    hashU64(&hasher, report.warnings.len);
    for (report.warnings) |warning| hashU64(&hasher, @intFromEnum(warning));
    hashU64(&hasher, report.summary.len);
    hashBytes(&hasher, report.summary);
    return hasher.final();
}

